--
-- Table structure for table `tourist_places`
--

DROP TABLE IF EXISTS `tourist_places`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tourist_places` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `name` text NOT NULL,
  `address` text,
  `region_id` int DEFAULT NULL,
  `latitude` float DEFAULT NULL,
  `longitude` float DEFAULT NULL,
  `description` text,
  `ticket_price_info` json DEFAULT NULL,
  `ticket_price_min` decimal(15,2) DEFAULT NULL,
  `ticket_price_max` decimal(15,2) DEFAULT NULL,
  `review_count` int DEFAULT '0',
  `average_rating` float DEFAULT '0',
  `website_url` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  UNIQUE KEY `slug` (`slug`),
  KEY `region_id` (`region_id`),
  CONSTRAINT `tourist_places_ibfk_1` FOREIGN KEY (`region_id`) REFERENCES `regions` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
