INSERT INTO `tourist_places` VALUES (1,'4adc974c-c68f-4191-80a2-cd2736459771','kampung-batik-laweyan-4adc97','Kampung Batik Laweyan','Jl. Dr. Rajiman No.521, Laweyan, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57148',1,-7.56988,110.797,'Kampung Batik Laweyan di Kota Solo adalah kawasan wisata batik yang telah ada sejak Kerajaan Pajang tahun 1546 M. Berlokasi di lahan seluas 24 hektar, kawasan ini terdiri dari tiga blok dan dihuni oleh ratusan pengrajin batik dengan berbagai motif dan harga. Selain menjadi sentra batik, Laweyan juga menyimpan kekayaan arsitektur Jawa kuno.','{\"Paket 1\": 25000, \"Paket 2\": 37000, \"Paket 3\": 50000, \"Keterangan\": {\"Paket 1\": \"Keliling Kampung, Free Minum, Free Guide, Durasi 1 Jam\", \"Paket 2\": \"Membatik, Free Guide, Free Minum, Durasi 1.5 Jam\", \"Paket 3\": \"Membatik dan Keliling Kampung, Free Minum, Free Guide, Durasi 2.5 Jam\"}}',25000.00,50000.00,325,4.4,'https://kampoengbatiklaweyan.org/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(2,'3812c9bd-eb9c-4995-8bea-e0ecc7ffa505','kampung-batik-kauman-3812c9','Kampung Batik Kauman','Jl. Trisula III No.1, Kauman, Kec. Ps. Kliwon, Kota Surakarta, Jawa Tengah 57112',1,-7.57341,110.826,'Kampung Wisata Batik Kauman Solo adalah kompleks kampung wisata yang berfokus pada batik sebagai daya tarik utamanya. Di dalam kampung ini, para pengunjung dapat berkunjung dan berbelanja di toko-toko batik yang batiknya dibuat langsung oleh pengrajin batik dari kampung ini. Selain itu, di kampung wisata ini para pengunjung dapat belajar membatik dengan tarif tertentu. Bangunan-bangunan di kampung batik ini memiliki gaya arsitektur khas Jawa dan Belanda yang membuat gang-gang di kampung batik ini menjadi sangat instagramable. Di kompleks kampung ini pun terdapat beberapa kafe-kafe kekinian yang dapat pengunjung kunjungi untuk bersantai dan beristirahat sebentar.','0',0.00,0.00,1972,4.7,'https://kampungbatikkauman.wixsite.com/kaumansolo','2025-06-18 18:26:39','2025-06-18 18:26:39'),(3,'6f28b49c-5123-4a65-a4a9-8b27f684b609','museum-radya-pustaka-6f28b4','Museum Radya Pustaka','Jl. Slamet Riyadi No.275, Sriwedari, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57141',1,-7.56846,110.814,'Museum Radya Pustaka adalah sebuah museum yang terletak di Surakarta, Indonesia. Didirikan pada tahun 1890, museum ini merupakan museum tertua kedua di Indonesia (yang tertua adalah Museum Nasional Indonesia di Jakarta). Museum ini menyimpan berbagai literatur berbahasa Jawa Kuno dan Belanda. Museum ini terletak di dalam kompleks taman Taman Sriwedari.','{\"Umum\": 10000, \"Pelajar\": 7500, \"Keterangan\": \"Gratis untuk Pelajar Asal Solo Khusus Hari Selasa\", \"Turis Asing\": 20000, \"Rombongan (Min 50)\": {\"Umum\": 7500, \"Pelajar\": 5000}, \"Pelajar Pemegang KIA (Hari Libur)\": 5000}',5000.00,20000.00,1184,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(4,'135be886-1280-4cd0-8f5b-380caa4b0c49','museum-batik-danar-hadi-135be8','Museum Batik Danar Hadi','Jl. Slamet Riyadi No.261, Sriwedari, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57141',1,-7.56869,110.816,'Museum Batik Danar Hadi menampilkan lebih dari 10.000 koleksi kain batik dari berbagai daerah di Indonesia, menjadikannya salah satu koleksi batik terbanyak yang diakui oleh MURI. Terletak di kompleks Rumah Batik Danar Hadi, museum ini juga menyajikan proses pembuatan batik secara langsung.','{\"Umum\": 45000, \"Pelajar\": 25000}',25000.00,45000.00,2419,4.7,'https://danarhadibatik.com/id/danar-hadi-world#dh-house','2025-06-18 18:26:39','2025-06-18 18:26:39'),(5,'06733aae-b3f5-4ff8-9dbb-b09348dd101b','solo-safari-06733a','Solo Safari','Jl. Ir. Sutami No.109, Jebres, Kec. Jebres, Kota Surakarta, Jawa Tengah 57126',1,-7.56465,110.859,'Solo Safari adalah destinasi wisata edukasi satwa seluas 14 hektar yang dikelola oleh Taman Safari Indonesia sejak 27 Januari 2023. Menampung lebih dari 400 satwa dari 90 spesies, pengunjung dapat menikmati pengalaman interaktif dengan berbagai zona satwa endemik Indonesia serta fasilitas hiburan seperti Paint and Brush, Gokart, Dino Ride, dan Savannah Zipline.','{\"Premium\": {\"Weekday\": {\"Dewasa\": 90000, \"Anak-anak\": 65000}, \"Weekend\": {\"Dewasa\": 110000, \"Anak-anak\": 80000}}, \"Regular\": {\"Weekday\": {\"Dewasa\": 55000, \"Anak-anak\": 45000}, \"Weekend\": {\"Dewasa\": 75000, \"Anak-anak\": 60000}}, \"Keterangan\": {\"Bayi\": \"Dibawah 2 tahun, tinggi <80cm Free Ticket\", \"Anak-anak\": \"Usia 2–6 tahun, tinggi badan maksimal 120cm\"}}',45000.00,110000.00,18302,4.1,'http://solosafari.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(6,'e62d4721-613c-44ed-a778-43304a4cd50b','keraton-surakarta-e62d47','Keraton Surakarta','Jl. Kamandungan, Baluwarti, Kec. Ps. Kliwon, Kota Surakarta, Jawa Tengah 57144',1,-7.57774,110.828,'Keraton Surakarta Hadiningrat adalah istana kerajaan yang terletak di Kota Surakarta, Jawa Tengah. Keraton ini didirikan oleh Sunan Pakubuwono II pada abad ke-18 sebagai pengganti Keraton Kartasura yang rusak. Keraton ini merupakan pusat pemerintahan Kesunanan Surakarta dan menjadi pusat kebudayaan Jawa.','35000',35000.00,35000.00,15715,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(7,'aeba805a-a2e9-46eb-9980-84cc5cfb3639','de-tjolomadoe-aeba80','De Tjolomadoe','Jl. Adisucipto No.1, Paulan Wetan, Malangjiwan, Kec. Colomadu, Kabupaten Karanganyar, Jawa Tengah 57177',2,-7.53413,110.75,'De Tjolomadoe adalah bekas pabrik gula peninggalan masa Hindia Belanda yang kini dialihfungsikan menjadi museum industri, pusat konvensi, dan kawasan komersial. Terletak di Colomadu, Karanganyar, tempat ini menghadirkan edukasi sejarah industri tebu dalam suasana arsitektur kolonial yang telah direstorasi.','{\"Dewasa\": 30000, \"Pelajar\": 25000, \"Turis Asing\": 200000}',25000.00,200000.00,21515,4.6,'http://www.detjolomadoe.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(8,'7e3182b7-a0f2-4a25-8348-edcb51723aeb','agrowisata-sondokoro-7e3182','Agrowisata Sondokoro','Jl. Mangkunegara Bojonegara, Nglande Wetan, Ngijo, Kec. Tasikmadu, Kabupaten Karanganyar, Jawa Tengah 42454',2,-7.5763,110.932,'Agrowisata Sondokoro adalah destinasi wisata keluarga yang menggabungkan pertanian, perkebunan, dan kebun binatang mini. Pengunjung dapat menikmati wahana permainan, taman lalu lintas, wisata kereta klasik, kolam renang, flying fox, dan terapi ikan.','5000',5000.00,5000.00,5147,4.1,'https://agrowisata-sondokoro.blogspot.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(9,'18903694-0e4a-4a51-aa35-371134a7b53e','taman-balekambang-189036','Taman Balekambang','Jl. Balekambang, Manahan, Kec. Banjarsari, Kota Surakarta, Jawa Tengah 57139',1,-7.55248,110.805,'Taman Balekambang merupakan taman bersejarah di Surakarta yang dibangun oleh KGPAA Mangkunegara VII pada tahun 1921 untuk kedua putrinya. Taman ini terdiri dari taman air (Partini Tuin) dan hutan kota (Partinah Bosch), dan kini berfungsi sebagai ruang terbuka multifungsi untuk rekreasi, edukasi, seni, budaya, dan konservasi lingkungan','5000',5000.00,5000.00,4658,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(10,'d3694ccf-665a-4e02-8bab-0c68db3c5d2c','museum-keris-nusantara-d3694c','Museum Keris Nusantara','Jl. Bhayangkara No.2, Sriwedari, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57141',1,-7.56903,110.811,'Museum Keris Nusantara menyimpan sekitar 409 koleksi keris berbagai jenis dan ukuran, serta 38 tombak dan benda-benda pusaka bersejarah lainnya. Museum ini dilengkapi dengan video visual mengenai perjalanan keris di Indonesia dan ruang pembelajaran keris bagi pengunjung.','{\"Weekday\": {\"Umum\": 7500, \"Pelajar\": 5000, \"Turis Asing\": 15000, \"Pelajar (Pemegang KIA)\": 4000, \"Rombongan (Min 50 Orang)\": {\"Umum\": 5000, \"Pelajar\": 4000}}, \"Weekend\": {\"Umum\": 10000, \"Pelajar\": 7500, \"Turis Asing\": 20000, \"Pelajar (Pemegang KIA)\": 5000, \"Rombongan (Min 50 Orang)\": {\"Umum\": 7500, \"Pelajar\": 5000}}}',4000.00,20000.00,2503,4.7,'https://uptmuseum.surakarta.go.id/?id=3&p=ss','2025-06-18 18:26:39','2025-06-18 18:26:39'),(11,'605cce5f-57bf-4ed2-8c3a-e35419cfbc12','tumurun-private-museum-605cce','Tumurun Private Museum','Jl. Kebangkitan Nasional No. 2, \n Sriwedari, Laweyan, Surakarta, Jawa Tengah 57141',1,-7.57041,110.816,'Tumurun Private Museum adalah museum pribadi milik keluarga Lukminto, pendiri PT Sritex, yang dibuka untuk umum sejak April 2018. Museum ini memamerkan berbagai karya seni kontemporer dan modern dari koleksi pribadi keluarga.','25000',25000.00,25000.00,2451,4.8,'https://www.tumurunmuseum.org/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(12,'e5319fdc-4cf5-4ea1-8091-71b9bdf15a3f','monumen-pers-nasional-e5319f','Monumen Pers Nasional','Jl. Gajah Mada No.59, Timuran, \n Kec. Banjarsari, Kota Surakarta, Jawa Tengah 57132',1,-7.56505,110.818,'Monumen Pers Nasional adalah museum khusus media massa nasional Indonesia yang terletak di Surakarta. Koleksinya meliputi teknologi komunikasi dan reportase, seperti mesin ketik, pemancar, telepon, serta memorabilia tokoh wartawan nasional.','0',0.00,0.00,2485,4.7,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(13,'1d36ea15-c72d-470b-a521-3880af2c0594','benteng-vastenburg-1d36ea','Benteng Vastenburg','Jalan Jenderal Soedirman, Kelurahan Kedung Lumbu, Kecamatan Pasar Kliwon, Surakarta, Jawa Tengah, Indonesia, 57133 ​',1,-7.57195,110.831,'Benteng Vastenburg adalah benteng bersejarah di Surakarta, Jawa Tengah, yang dibangun pada tahun 1745 atas perintah Gubernur Jenderal Gustaaf Willem van Imhoff. Benteng ini dibangun untuk mengawasi Keraton Surakarta dan menjadi pusat militer, administrasi, tempat tinggal Residen Surakarta, dan juga menampung tentara Belanda.','0',0.00,0.00,15843,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(14,'ec937893-f992-4332-9073-a3452950efff','taman-cerdas-soekarno-hatta-ec9378','Taman Cerdas Soekarno-Hatta','Jl. Ki Hajar Dewantara RT02 RW25, Jebres, Jl. Surya I Tengah No.25, RT.03/RW.25, Jebres, Kec. Jebres, Kota Surakarta, Jawa Tengah 57126',1,-7.55403,110.853,'Taman Cerdas Soekarno Hatta adalah sebuah taman kota di Solo yang menawarkan kombinasi antara ruang terbuka hijau, tempat bersantai, dan destinasi wisata edukasi. Taman ini dilengkapi dengan fasilitas yang lengkap dan menjadi pilihan menarik untuk dikunjungi saat memiliki waktu luang, terutama bagi yang mencari pengalaman wisata yang edukatif dan menyenangkan','{\"Dewasa\": 5000, \"Anak-anak\": 2000}',2000.00,5000.00,5917,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(15,'6fa30dbd-fa81-4411-ab18-f93d50b16251','kereta-api-uap-jaladara-6fa30d','Kereta Api Uap Jaladara','Jalan Slamet Riyadi No. 502\n Purwosari, Laweyan, Surakarta, Jawa Tengah 57142',1,-7.56157,110.797,'Kereta Api Uap Jaladara, atau Sepur Kluthuk Jaladara, adalah kereta wisata bersejarah yang beroperasi di Kota Solo. Menggunakan lokomotif uap D1410 buatan Jerman tahun 1896, kereta ini melintasi jalur sepanjang 5,6 km dari Stasiun Purwosari hingga Stasiun Solo Kota, melewati Jalan Slamet Riyadi. Dengan dua gerbong berkapasitas total 72 penumpang, perjalanan ini menawarkan pengalaman nostalgia sambil menikmati pemandangan kota Solo.','{\"Sewa\": 3500000, \"Umum\": 120000}',120000.00,3500000.00,2574,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(16,'ba6e7510-0ccd-4202-9fe2-6362ca5fa68e','museum-manusia-purba-sangiran-klaster-krikilan-ba6e75','Museum Manusia Purba Sangiran Klaster Krikilan','Jl. Sangiran No.Km.4, Kebayanan II, Krikilan, Kec. Kalijambe, Kabupaten Sragen, Jawa Tengah 57275',3,-7.45569,110.834,'Museum Manusia Purba Sangiran Klaster Krikilan di Dusun Ngampon, Sragen, merupakan visitor center utama Situs Sangiran (warisan dunia UNESCO). Memiliki tiga ruang pamer: Kekayaan Situs Sangiran, Langkah Kemanusiaan, dan Masa Keemasan Homo erectus. Menampilkan fosil Homo erectus Sangiran 17, fauna prasejarah, serta kisah peneliti dan tokoh lokal. Kawasan Sangiran mencakup 59,21 km² dan menyimpan lebih dari 50% temuan Homo erectus dunia.','{\"Asing\": 30000, \"Domestik\": 15000}',15000.00,30000.00,1770,4.6,'http://sangiran.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(17,'fc79209c-ee6d-4c3e-b9fd-fd22e9f6d4da','museum-manusia-purba-sangiran-klaster-ngebung-fc7920','Museum Manusia Purba Sangiran Klaster Ngebung','GVX5+WR, Dusun 3, Bukuran, Kec. Kalijambe, Kabupaten Sragen, Jawa Tengah 57275',3,-7.44169,110.84,'Museum Manusia Purba Sangiran Klaster Ngebung menampilkan sejarah awal eksplorasi Situs Sangiran oleh para peneliti seperti Raden Saleh dan G.H.R. von Koenigswald. Museum ini menyajikan perjalanan panjang pengakuan Situs Sangiran sebagai warisan dunia melalui pameran artefak, dokumentasi penelitian, dan diorama interaktif.','{\"Asing\": 30000, \"Domestik\": 15000}',15000.00,30000.00,6559,4.5,'http://sangiran.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(18,'5053d5b6-7c7e-41d6-86e9-adc483e7859b','museum-manusia-purba-sangiran-klaster-bukuran-5053d5','Museum Manusia Purba Sangiran Klaster Bukuran','GVX5+WR, Dusun 3, Bukuran, Kec. Kalijambe, Kabupaten Sragen, Jawa Tengah 57275',3,-7.45106,110.862,'Museum Purba Sangiran Klaster Bukuran fokus pada teori evolusi manusia dan faktor-faktor yang mempengaruhinya. Museum dua lantai ini menyajikan materi secara populer dan interaktif, termasuk pameran tentang Homo Erectus dan lingkungan hidupnya di masa lalu.','{\"Asing\": 30000, \"Domestik\": 15000}',15000.00,30000.00,421,4.5,'http://sangiran.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(19,'26b178a2-7a57-4cbb-b552-f32cf0f0a6c5','museum-lapangan-manyarejo-26b178','Museum Lapangan Manyarejo','Dsn. Grogolan RT 10, Ds. Manyarejo Kec. Plupuh, Sragen, Jawa Tengah, Indonesia',3,-7.4485,110.861,'Museum Lapangan Manyarejo merupakan museum lapangan yang menampilkan kondisi asli lokasi penggalian fosil di Sangiran. Museum ini memberikan penghargaan kepada warga lokal yang berkontribusi dalam penelitian serta menyajikan informasi beserta bukti-bukti ilmiah yang mudah dipahami pengunjung.','{\"Asing\": 20000, \"Domestik\": 5000}',5000.00,20000.00,114,4.5,'http://sangiran.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(20,'0508d096-6a6c-4da5-b8f1-6e8f3108d6cf','pura-mangkunagaran-0508d0','Pura Mangkunagaran','Jl. Ronggowarsito, Keprabon, Kec. Banjarsari, Kota Surakarta, Jawa Tengah 57131',1,-7.56694,110.823,'Dibangun pada tahun 1757 oleh Raden Mas Said (Pangeran Sambernyawa), Pura Mangkunegaran adalah istana bersejarah yang menggabungkan arsitektur tradisional Jawa dan Eropa. Kompleks ini terdiri dari Pamedan, Pendopo Ageng, Pringgitan, Ndalem Ageng, Keputren, dan Pracimoyasa, serta menyimpan berbagai koleksi seni dan artefak kerajaan.','{\"Asing\": 50000, \"Domestik\": 30000}',30000.00,50000.00,8785,4.7,'https://mangkunegaran.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(21,'98d7ef92-d293-4791-98a9-26cd8c0bf9ef','museum-lokananta-98d7ef','Museum Lokananta','Jl. A. Yani No.379 A, Kerten, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57143.',1,-7.55773,110.795,'Museum Lokananta adalah studio rekaman pertama dan tertua di Indonesia, didirikan pada 29 Oktober 1956 oleh Raden Maladi, Kepala Jawatan RRI. Terletak di Laweyan, Solo, museum ini berdiri di atas lahan seluas 21.150 m² dan memiliki ruang rekaman terbesar di Indonesia. Awalnya berfungsi sebagai pabrik piringan hitam untuk merekam siaran RRI, Lokananta kini menjadi pusat dokumentasi sejarah musik Indonesia, menyimpan koleksi rekaman musik, pidato kenegaraan, dan peralatan rekaman kuno. Revitalisasi pada 2022 menjadikannya destinasi wisata musik dan pusat industri kreatif.','{\"WithGuide\": {\"Turis\": 70000, \"Remaja\": 35000, \"Senior\": 25000, \"Pelajar\": 25000, \"Anak-anak\": 25000}, \"WithoutGuide\": {\"Turis\": 50000, \"Remaja\": 35000, \"Senior\": 25000, \"Pelajar\": 25000, \"Anak-anak\": 25000}}',25000.00,70000.00,2027,4.8,'https://galerilokananta-online.globaltix.com/attraction/galeri-lokananta-58140','2025-06-18 18:26:39','2025-06-18 18:26:39'),(22,'45311c36-6f51-48cb-8080-afe1a9493dd5','candi-bubrah-45311c','Candi Bubrah','Taman Martani , Kalasan , Sleman , Daerah Istimewa Yogyakarta, Klurakbaru, Tlogo, Kec. Prambanan, Kabupaten Klaten, Jawa Tengah 57454',4,-7.7465,110.493,'Candi Bubrah adalah candi Buddha abad ke-9 yang terletak di kawasan Prambanan, Klaten. Dibangun pada masa Kerajaan Mataram Kuno, candi ini memiliki struktur unik dengan satu stupa utama dikelilingi oleh delapan dan enam belas stupa kecil, mencerminkan konsep mandala dalam arsitektur Buddha. Nama \"Bubrah\" berarti \"rusak\" dalam bahasa Jawa, merujuk pada kondisi candi saat ditemukan. Pemugaran selesai pada 14 Desember 2017, mengembalikan kemegahan candi sebagai bagian dari kompleks Candi Sewu.','{\"Domestik\": {\"Dewasa\": {\"Harga Promo\": \"Tergantung Promo\", \"Harga Normal\": 50000}, \"Anak-anak (3–10 tahun)\": {\"Harga Promo\": \"Tergantung Promo\", \"Harga Normal\": 25000}}, \"Mancanegara\": {\"Dewasa\": {\"Harga Promo\": \"Tidak Ada\", \"Harga Normal\": 375000}, \"Anak-anak (3–10 tahun)\": {\"Harga Promo\": \"Tidak Ada\", \"Harga Normal\": 225000}}}',25000.00,375000.00,307,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(23,'4d1a2ccb-d42f-45fe-99d1-1653c7f51dee','candi-merak-4d1a2c','Candi Merak','Dusun I, Candi, Kec. Karangnongko, Kabupaten Klaten, Jawa Tengah 57483',4,-7.66971,110.553,'Candi Merak adalah kompleks candi Hindu peninggalan Kerajaan Mataram Kuno, diperkirakan dibangun antara abad ke-8 hingga ke-9 Masehi. Terletak di Desa Karangnongko, Klaten, kompleks ini terdiri dari satu candi induk dan tiga candi perwara. Nama \"Merak\" berasal dari keberadaan burung merak di sekitar lokasi saat candi ditemukan pada 1925. Candi ini menampilkan relief dan arca dewa-dewi Hindu seperti Ganesha, Agastya, dan Durga, serta hiasan kalamakara pada tangga masuk. Pemugaran dilakukan antara 2007 hingga 2011, mengembalikan keindahan arsitektur candi.','0',0.00,0.00,506,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(24,'0e881ef7-c269-4ed5-b8a2-589f1cd87019','museum-astana-oentara-0e881e','Museum Astana Oentara','Jl. Nayu, Nusukan, Kec. Banjarsari, Kota Surakarta, Jawa Tengah 57135',1,-7.54731,110.824,'Astana Oetara adalah rumah peristirahatan terakhir KGPAA Mangkunegara VI yang menyimpan memori penting sejarah Indonesia dari masa kolonial hingga reformasi. Situs ini telah ditetapkan sebagai Cagar Budaya oleh Pemerintah Kota Surakarta pada 21 Mei 2021. Kini, Astana Oetara menjadi pusat kegiatan masyarakat dan museum hidup yang terbuka bagi publik untuk mengenal nilai-nilai kepemimpinan beliau.','{\"TiketWithZiarah\": {\"Balita\": 0, \"Dewasa\": 25000, \"Anggota\": 0, \"Pelajar\": 7500, \"Anak-anak\": 7500}, \"TiketWithoutZiarah\": {\"Balita\": 0, \"Dewasa\": 20000, \"Anggota\": 0, \"Pelajar\": 5000, \"Anak-anak\": 5000}}',0.00,25000.00,40,4.9,'https://www.astanaoetara.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(25,'2ad9e006-5b85-4cd3-8b95-ea34fb7b85f5','taman-sriwedari-2ad9e0','Taman Sriwedari','Jl. Slamet Riyadi No.275, Sriwedari, Kec. Laweyan, Kota Surakarta, Jawa Tengah 57141',1,-7.56856,110.813,'Taman Sriwedari di Solo adalah destinasi legendaris yang menawarkan pengalaman budaya dan rekreasi bagi pengunjung. Didirikan oleh Raja Pakubuwono X pada tahun 1887, taman ini awalnya digunakan sebagai tempat peristirahatan keluarga keraton dan kebun binatang. Kini, taman ini berfungsi sebagai Taman Hiburan Rakyat (THR) yang menghadirkan atraksi-atraksi baru, cocok untuk bersantai bersama keluarga.','0',0.00,0.00,6640,4.3,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(26,'3aa806df-ec2f-4ea1-9004-5edb681e9125','taman-hutan-raya-mangkunagoro-3aa806','Taman Hutan Raya Mangkunagoro','Tambak, Dusun Sukuh, Berjo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.62323,111.137,'Taman Hutan Raya Mangkunagoro I adalah kawasan konservasi alam sekaligus destinasi wisata alam dan edukasi yang terletak di lereng Gunung Lawu, Karanganyar. Tahura ini menawarkan keindahan hutan pegunungan dengan udara sejuk serta berbagai jalur trekking dan wisata alam. Sebagai lokasi edukasi lingkungan, Tahura Mangkunagoro juga menyediakan informasi tentang keanekaragaman flora dan fauna di kawasan tersebut. Tempat ini sangat cocok untuk pecinta alam, pelajar, maupun keluarga yang ingin menikmati ketenangan dan keasrian hutan tropis.','{\"Dewasa\": 3000, \"Anak-anak\": 2500}',2500.00,3000.00,741,4.5,'http://www.tahuramangkunagoro.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(27,'136d372d-03d8-4fba-9ba3-5352c482e04a','semar-edupark-136d37','Semar Edupark','Jl. Raya Solo - Tawangmangu, Gedangan, Salam, Kec. Karangpandan, Kabupaten Karanganyar, Jawa Tengah 57791',2,-7.62179,111.083,'Semar Edupark adalah destinasi wisata alam dan edukasi yang berlokasi di Karanganyar, Jawa Tengah, dengan konsep perpaduan antara keindahan alam dan fasilitas modern. Tempat ini menawarkan berbagai aktivitas menarik, mulai dari taman bermain, spot foto, restoran, hingga ruang pertemuan dan area outdoor untuk acara keluarga maupun bisnis. Dengan suasana sejuk, area yang luas, dan beragam pilihan kegiatan, Semar Edupark cocok untuk semua usia dan menjadi tempat rekreasi yang lengkap dalam satu lokasi.','{\"mini_golf\": \"30000\", \"entry_ticket\": \"0\", \"animal_feeding\": \"10000\", \"fishing_package\": \"30000\", \"outbound_starting_from\": \"90000\", \"picnic_package_starting_from\": \"150000\"}',0.00,150000.00,964,4.3,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(28,'b1f180af-3e71-4109-afcd-b406f900ef9d','ronce-stable-b1f180','Ronce Stable','Jl. Tentara Pelajar, Empat, Tepisari, Kec. Polokarto, Kabupaten Sukoharjo, Jawa Tengah 57555',5,-7.67137,110.916,'Ronce Stable adalah destinasi wisata unik di Tepisari, Sukoharjo, yang menawarkan pengalaman menunggang kuda pacuan bagi pecinta adrenalin. Selain berlatih berkuda, pengunjung juga bisa menikmati kuliner lokal dan berbagai spot foto menarik seperti taman bunga, saung, dan trek berkuda. Tersedia pula properti foto bertema koboi dan vintage yang menambah keseruan wisata.','{\"village_tour_10_minutes\": \"25000\", \"private_horseback_riding_member\": \"130000\", \"rubber_forest_tour_40_50_minutes\": \"150000\", \"private_horseback_riding_non_member\": \"150000\"}',25000.00,150000.00,92,4.7,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(29,'e5a6608c-2c4e-4569-9257-aaf98faaee52','alun-alun-kidul-surakarta-e5a660','Alun-Alun Kidul Surakarta','alun alun kidul, Kec. Ps. Kliwon, Kota Surakarta, Jawa Tengah 57118',1,-7.58219,110.826,'Alun-alun Kidul Surakarta adalah tempat yang ramai dikunjungi masyarakat Solo, di mana mereka bisa menikmati sore hari dengan berbagai aktivitas seperti berolahraga, duduk santai, atau mencicipi jajanan lokal. Di sini, pengunjung juga bisa mencoba aktivitas masangin, berjalan melewati dua beringin kembar dengan mata tertutup, yang dipercaya dapat mewujudkan permohonan. Selain itu, terdapat kerbau bule koleksi Keraton Surakarta yang bisa diberi makan, serta fasilitas andong untuk mengelilingi kawasan tersebut','0',0.00,0.00,26469,4.5,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(30,'f3a2021b-f939-4fc9-ac45-c8dbdde00bc6','cepogo-cheese-park-f3a202','Cepogo Cheese Park','Dusun II, Genting, Kec. Cepogo, Kabupaten Boyolali, Jawa Tengah 57362',6,-7.5061,110.5,'Cepogo Cheese Park merupakan destinasi wisata keluarga bertema edukasi peternakan dan produksi keju yang berada di dataran tinggi Cepogo, Boyolali. Dengan latar pemandangan Gunung Merapi dan Merbabu, tempat ini menyuguhkan pengalaman berinteraksi langsung dengan hewan ternak seperti sapi dan kambing perah, serta proses pembuatan keju secara tradisional. Tersedia juga area bermain anak, spot foto menarik, dan restoran yang menyajikan berbagai produk olahan susu. Suasana alam yang sejuk dan konsep wisata edukatif menjadikannya pilihan ideal untuk liburan keluarga maupun kunjungan sekolah.','{\"cheese_park\": {\"weekday\": 20000, \"weekend\": 25000}, \"paket_5_activity\": {\"weekday\": 49000, \"weekend\": 49000}, \"tiket_combo_2_wahana_a\": {\"weekday\": 35000, \"weekend\": 45000}}',20000.00,49000.00,6865,4.5,'https://cimorydairyland.com/estate/cepogo-cheese-park','2025-06-18 18:26:39','2025-06-18 18:26:39'),(31,'266f71ec-c176-4be0-81f8-b84f24260950','museum-mini-sisa-hartaku-266f71','Museum Mini Sisa Hartaku','Jl. Petung Merapi, Petung, Kepuharjo, Kec. Cangkringan, Kabupaten Sleman, Daerah Istimewa Yogyakarta 55583',8,-7.60054,110.449,'Museum Mini Sisa Hartaku adalah museum kecil yang berdiri sebagai saksi bisu dahsyatnya letusan Gunung Merapi tahun 2010. Terletak di Dusun Petung, Sleman, museum ini memamerkan benda-benda sisa erupsi seperti sepeda motor, peralatan rumah tangga, tulang hewan, hingga foto-foto kondisi desa setelah bencana. Tempat ini menawarkan pengalaman emosional dan reflektif, menggambarkan dampak bencana alam dan ketangguhan masyarakat lereng Merapi. Museum ini dikelola oleh warga lokal dan menjadi bagian dari jalur wisata edukasi Merapi.','5000',5000.00,5000.00,3154,4.7,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(32,'63f73723-ff10-4aa6-aae2-688acabf8a6f','kebun-raya-indrokilo-63f737','Kebun Raya Indrokilo','Unnamed Road, Area Sawah, Butuh, Kec. Mojosongo, Kabupaten Boyolali, Jawa Tengah 57482',6,-7.55902,110.631,'Kebun Raya Indrokilo merupakan kawasan konservasi dan wisata edukasi botani yang terletak di Mojosongo, Boyolali. Taman ini mengusung konsep taman tematik yang memadukan fungsi konservasi tumbuhan, penelitian, pendidikan, dan pariwisata. Di area seluas lebih dari 8 hektar, pengunjung dapat menjumpai berbagai zona menarik seperti Taman Labirin, Gerbang Pasingsingan, patung tokoh pewayangan Bima, dan rumah kaca (greenhouse) berisi koleksi tanaman langka. Suasananya yang sejuk dan asri menjadikannya tempat yang cocok untuk rekreasi keluarga sekaligus pembelajaran lingkungan hidup dan pelestarian flora Indonesia.','5500',5500.00,5500.00,1571,4.4,'https://kebunrayaindrokilo.boyolali.go.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(33,'1bec972a-7430-4de1-aed3-82dcabc6e15f','umbul-tlatar-boyolali-1bec97','Umbul Tlatar Boyolali','Jl. Pangeran Diponegoro, Dusun 2, Kebonbimo, Kec. Boyolali, Kabupaten Boyolali, Jawa Tengah 57316',6,-7.4941,110.621,'Umbul Tlatar adalah objek wisata air berbasis sumber mata air alami yang berada di Kecamatan Boyolali. Destinasi ini dikenal sebagai tempat rekreasi keluarga yang menggabungkan wisata air, kuliner, edukasi, dan konservasi alam. Sumber air di Umbul Tlatar berasal langsung dari mata air pegunungan Merapi-Merbabu, menjadikan airnya sangat jernih dan segar. Terdapat kolam renang alami, kolam terapi ikan, kolam pancing, wahana permainan anak, dan edukasi pertanian hidroponik. Suasana sejuk dan fasilitas lengkap membuat Umbul Tlatar cocok untuk wisata harian bersama keluarga.','15000',15000.00,15000.00,2803,4.2,'-','2025-06-18 18:26:39','2025-06-18 18:26:39'),(34,'c97f3aae-44bd-44db-bed9-d5f0b8b2975d','wisata-terpadu-bukit-pertapan-bayat-c97f3a','Wisata Terpadu Bukit Pertapan Bayat','Kebon, Kec. Bayat, Kabupaten Klaten, Jawa Tengah 57462',4,-7.77312,110.646,'Bukit Pertapan Klaten adalah destinasi wisata alam yang memiliki nilai sejarah dan edukasi, terletak di Desa Kebon, Bayat, Klaten. Dahulu digunakan sebagai tempat bertapa Panembahan Menanglase, kini kawasan ini menjadi tempat rekreasi yang menyuguhkan pemandangan indah, udara sejuk, serta berbagai fasilitas edukatif dan rekreatif untuk semua kalangan.','{\"Tiket Masuk\": {\"Umum\": 3000}}',3000.00,3000.00,177,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(35,'19fd01c9-0bfc-4cd5-8b81-0c587252c03b','lembah-gunung-madu-19fd01','Lembah Gunung Madu','Jl. Raya Simo-Klego KM.5, Gunung Madu, Simo, Tanjung, Klego',6,-7.41038,110.69,'Lembah Gunung Madu merupakan destinasi wisata alam dan edukatif yang terletak di kaki Gunung Madu, Desa Simo, Boyolali. Menyajikan perpaduan panorama alam yang asri, situs sejarah gua-gua peninggalan, mini zoo, serta wahana rekreasi modern, tempat ini cocok untuk wisata keluarga, edukasi anak, hingga aktivitas petualangan.','{\"Parkir\": {\"Mobil\": 5000, \"Sepeda Motor\": 4000}, \"Wahana\": {\"Flying Fox\": 20000, \"Sepeda Gantung\": 25000}, \"Tiket Masuk\": 10000}',10000.00,10000.00,2992,4,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(36,'8368e152-bf71-4c40-87cc-5b6c46ac6b38','umbul-ponggok-8368e1','Umbul Ponggok','Jl. Delanggu- Polanharjo No.Ds, Jeblogan, Ponggok, Kec. Polanharjo, Kabupaten Klaten, Jawa Tengah 57474',4,-7.61381,110.636,'Umbul Ponggok adalah kolam alami berisi mata air jernih yang telah ada sejak abad ke-19. Terletak di Klaten, tempat ini terkenal sebagai destinasi wisata edukasi dan rekreasi air dengan konsep underwater experience. Pengunjung bisa belajar tentang ekosistem air tawar sambil menikmati aktivitas snorkeling dan fotografi bawah air yang unik.','{\"Weekday\": 10000, \"Weekend\": 15000}',10000.00,15000.00,22101,4.5,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(37,'8cc4aaba-7305-44ff-ae25-bef6f7e79dbe','candi-sojiwan-8cc4aa','Candi Sojiwan','Jl. Banjarsari No.12 RT. 03, RT.03/RW.03, Kwaron, Kb. Dalem Kidul, Kec. Prambanan, Kabupaten Klaten, Jawa Tengah 57454',4,-7.76106,110.496,'Candi Sojiwan adalah candi peninggalan kebudayaan Buddha yang terletak di Kabupaten Klaten, Jawa Tengah. Ditemukan pada tahun 1813 dan telah dipugar pada tahun 2011, candi ini merupakan situs sejarah yang mengandung banyak prasasti, arca, dan ukiran yang menggambarkan kehidupan masyarakat pada zaman dahulu. Selain keindahan candi itu sendiri, pengunjung juga dapat menikmati keasrian taman sekitar candi yang dipenuhi rerumputan hijau dan pohon-pohon tinggi.','{\"Tiket Masuk\": {\"Umum\": 5000}}',5000.00,5000.00,2698,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(38,'1cfe57b2-c695-4f85-b27a-b8103f871656','gedung-djoeang-45-1cfe57','Gedung Djoeang 45','Kedung Lumbu, Kec. Ps. Kliwon, Kota Surakarta, Jawa Tengah',1,-7.57375,110.832,'Gedung Djoeang 45 adalah bangunan bersejarah yang dibangun pada masa penjajahan Belanda dan sekarang berfungsi sebagai tempat wisata sejarah yang modern. Terletak di pusat kota Solo, gedung ini memiliki arsitektur Eropa klasik dan menyajikan suasana yang estetik. Sejak tahun 2019, Gedung Djoeang 45 telah direvitalisasi dan menjadi destinasi populer untuk wisata sejarah, kuliner, dan foto-foto Instagramable.','\"{\\n  \\\"\\\"Tiket Masuk\\\"\\\": {\\n  \\\"\\\"Umum\\\"\\\": 15000\\n  }\\n }\"',15000.00,15000.00,799,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(39,'9cca5b46-08fd-449d-8aac-b00294ec7fa9','candi-plaosan-9cca5b','Candi Plaosan','Jl. Candi Plaosan, Dukuh Plaosan, Bugisan, Kec. Prambanan, Kabupaten Klaten, Jawa Tengah 57454',4,-7.74057,110.505,'Candi Plaosan adalah kompleks candi Buddha yang dibangun pada abad ke-9 M, terletak di Klaten, Jawa Tengah, dekat Yogyakarta. Keunikan candi ini terletak pada perpaduan arsitektur Hindu dan Buddha, simbol toleransi beragama antara Rakai Pikatan (Hindu) dan Pramudyawardhani (Buddha). Lingkungan sekitar candi dipenuhi sawah hijau yang asri, cocok untuk wisata sejarah, budaya, dan edukasi.','{\"Domestik\": {\"Dewasa\": 10000, \"Anak-anak\": 5000}, \"Turis Asing\": {\"Dewasa\": 20000, \"Anak-anak\": 10000}}',5000.00,20000.00,11086,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(40,'aeae6457-021a-4456-92dd-6e5a298adb87','the-heritage-palace-aeae64','The Heritage Palace','jalan Permata Raya Dukuh Tegal Mulyo rt.002/rw.008, Honggobayan, Pabelan, Kec. Kartasura, Kabupaten Sukoharjo, Jawa Tengah 57169',5,-7.55476,110.755,'The Heritage Palace Solo adalah objek wisata edukatif dan keluarga yang berlokasi di bekas pabrik gula Gembongan, Sukoharjo. Dibuka sejak 2018, tempat ini menghadirkan nuansa arsitektur klasik Eropa dengan berbagai wahana menarik seperti Museum Transportasi, Museum 3D, taman bermain anak (Kids Town), dan area outdoor bergaya Romawi. Cocok untuk belajar sejarah, berburu foto estetik, hingga wisata kuliner dan budaya dalam satu kawasan.','\"{\\n  \\\"Tiket Masuk Gate Outdoor\\\": 30000,\\n  \\\"Tiket Terusan (Outdoor + Indoor)\\\": {\\n  \\\"Weekday\\\": 55000,\\n  \\\"Weekend\\\": 65000\\n  },\\n  \\\"Anak-anak\\\": \\\"Gratis untuk tinggi badan di bawah 100 cm\\\",\\n }\"',30000.00,65000.00,12902,4.4,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(41,'d708a4d2-1966-457c-bdd4-0425af5fdc69','wisata-alam-batu-seribu-d708a4','Wisata Alam Batu Seribu','Gentan, Bulu, Pacinan, Gentan, Sukoharjo, Kabupaten Sukoharjo, Jawa Tengah 57563',5,-7.78805,110.838,'Wisata Alam Batu Seribu adalah destinasi wisata alam yang terletak di lereng Gunung Gajah Mungkur, Desa Gentan, Kabupaten Sukoharjo, Jawa Tengah. Tempat ini menawarkan pengalaman menyatu dengan alam melalui kolam renang alami dari sumber mata air, pemandangan hutan rimbun, batuan besar yang eksotis, dan udara segar pegunungan. Cocok untuk liburan keluarga, aktivitas outdoor, camping, hingga berburu sunset, Batu Seribu juga termasuk dalam kawasan Gunung Sewu UNESCO Global Geopark, menjadikannya wisata edukatif dan alami yang unik.','{\"Tiket Masuk\": {\"Umum\": 10000}}',10000.00,10000.00,1175,4.1,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(42,'ebf790b1-9c6b-4624-8ca4-c294bac73c96','candi-cetho-ebf790','Candi Cetho','Ceto, RT.01/RW.03, Cetho, Gumeng, Kec. Jenawi, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.59556,111.157,'Candi Cetho adalah destinasi yang wajib masuk daftar kunjunganmu. Berlokasi di ketinggian, candi ini menawarkan pemandangan spektakuler, udara sejuk, serta nuansa mistis yang khas. Candi peninggalan Kerajaan Majapahit ini juga masih digunakan sebagai tempat peribadatan umat Hindu hingga sekarang','{\"Tiket Masuk\": {\"Wisatawan Domestik\": 10000, \"Wisatawan Mancanegara\": 30000}}',10000.00,30000.00,11183,4.7,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(43,'c61c633b-cb1d-4c13-a848-e34705ce4fa4','candi-sukuh-c61c63','Candi Sukuh','Tambak, Berjo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.62731,111.132,'Candi Sukuh adalah candi Hindu peninggalan Kerajaan Majapahit yang terletak di kaki Gunung Lawu, Karanganyar, Jawa Tengah. Candi ini memiliki arsitektur unik yang mirip dengan candi suku Maya, berbentuk trapesium. Candi ini dikenal sebagai \"the last temple\" karena merupakan peninggalan terakhir dari kerajaan Majapahit. Candi Sukuh menjadi tempat wisata sejarah yang menarik dengan berbagai relief, patung, dan cerita sejarah yang tersimpan di dalamnya.','{\"Tiket Masuk\": {\"Lokal\": 7000, \"Mancanegara\": 25000}}',7000.00,25000.00,3633,4.6,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(44,'3d07604f-76ee-4b84-8145-e66f76b9dbbc','rumah-atsiri-indonesia-3d0760','Rumah Atsiri Indonesia','Jl. Watusambang, Watusambang, Plumbon, Kec. Tawangmangu, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.65496,111.102,'Rumah Atsiri Indonesia adalah destinasi wisata edukatif di Tawangmangu, Jawa Tengah, yang menyajikan pengalaman unik seputar minyak atsiri. Berkonsep eduwisata, tempat ini menawarkan museum, kebun tanaman aromatik, workshop kecantikan, serta restoran berbahan rempah. Suasana asri dan wangi alami menjadikannya tempat ideal untuk belajar sekaligus relaksas','{\"Tiket Masuk\": {\"Harga\": 50000}}',50000.00,50000.00,6809,4.7,'http://www.rumahatsiri.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(45,'dcdcfe7a-dd83-4222-b96f-08ada374be45','kebun-teh-kemuning-dcdcfe','Kebun Teh Kemuning','Jalan, Sumbersari, Kemuning, Ngargoyoso, Karanganyar Regency, Central Java 57794',2,-7.59552,111.133,'Kebun Teh Kemuning adalah destinasi wisata alam yang terletak di lereng Gunung Lawu, Karanganyar, Jawa Tengah. Dengan pemandangan hijau dan udara sejuk, kebun teh seluas 437 hektare ini menawarkan pengalaman unik bagi pengunjung, mulai dari tur petik teh, jalur hiking, hingga spot foto estetik. Kebun Teh Kemuning juga merupakan peninggalan Kerajaan Mangkunegaran yang pertama kali dibuka pada tahun 1814.','\"Gratis\"',0.00,0.00,1623,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(46,'54b1119c-e680-406d-9e89-387172a538ff','astana-giribangun-54b111','Astana Giribangun','Jl. Astana Giribangun, Dengkeng, Girilayu, Kec. Matesih, Kabupaten Karanganyar, Jawa Tengah 57781',2,-7.65211,111.071,'Astana Giribangun merupakan kompleks makam Presiden RI ke-2, Soeharto, yang terletak di lereng Gunung Lawu, Karanganyar. Selain sebagai tempat ziarah, kawasan ini menjadi destinasi wisata religi dan edukatif dengan nuansa tenang, sejarah kuat, dan pemandangan alam yang sejuk.','{\"Tiket Masuk\": {\"Harga\": 5000}}',50000.00,50000.00,506,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(47,'bc046fcd-ce61-460e-a4f6-70ba33872393','agrowisata-strawberry-tawangmangu-bc046f','Agrowisata Strawberry Tawangmangu','Kramat, Kalisoro, Kec. Tawangmangu, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.66223,111.145,'Kebun Strawberry Tawangmangu terletak di Kalisoro, Tawangmangu, Karanganyar, Jawa Tengah. Wisata ini menawarkan pengalaman edukasi yang menarik bagi pengunjung, terutama bagi mereka yang ingin memetik stroberi langsung dari kebun. Dikelola oleh petani lokal sejak 2001, kebun ini menampilkan berbagai jenis stroberi dengan kualitas unggul, yang dapat dipetik dan dinikmati langsung oleh pengunjung. Lokasinya yang berada di lereng Gunung Lawu memberikan udara sejuk dan pemandangan indah, menjadikannya tempat wisata favorit bagi keluarga, pelajar, dan wisatawan lainnya.','\"Gratis\"',0.00,0.00,163,4.7,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(48,'1aea6c1d-f575-463e-90aa-24272123bd95','taman-edukasi-intanpari-1aea6c','Taman Edukasi Intanpari','Jl. Jend. Gatot Subroto, Beningrejo, Gaum, Kec. Tasikmadu, Kabupaten Karanganyar, Jawa Tengah 57716',2,-7.58805,110.952,'Edupark Intanpari adalah destinasi wisata edukasi yang berada di Karanganyar, Jawa Tengah, yang menawarkan pengalaman liburan menyenangkan dan murah. Tempat ini cocok dikunjungi bersama keluarga atau rombongan. Edupark Intanpari menyajikan beragam wahana edukasi dan rekreasi yang bisa dinikmati oleh pengunjung dari berbagai kalangan usia. Lokasinya yang mudah dijangkau, dengan berbagai fasilitas yang nyaman, menjadikan tempat ini sangat populer untuk liburan edukatif.','{\"Tiket Masuk\": {\"Harga\": 7000}}',7000.00,7000.00,2976,4.2,'https://pudanekausahakaranganyar.id/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(49,'374342e0-0fbe-4616-a0eb-d75ed9b87df4','kemuning-skyhills-374342','Kemuning Skyhills','Jl. Karangpandan-Ngargoyoso, Sumbersari, Kemuning, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57794',2,-7.59541,111.133,'Kemuning Sky Hills adalah destinasi wisata agrowisata yang terletak di kawasan kebun teh Kemuning, Karanganyar. Dengan konsep wisata alam yang mengusung keindahan perbukitan teh dan udara segar dari lereng Gunung Lawu, tempat ini menawarkan berbagai aktivitas seru seperti berfoto di jembatan kaca, berkeliling menggunakan ATV, hingga menikmati pemandangan alam dari Rumah Kaca. Destinasi ini juga dilengkapi dengan spot foto Instagrammable, bukit Teletubies, dan fasilitas wisata yang nyaman.','{\"Tiket Masuk\": {\"Harga\": 10000}}',10000.00,10000.00,1756,4.6,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(50,'112c2eb5-2656-4bca-a2d3-e2691974a3f3','agrowisata-amanah-112c2e','Agrowisata Amanah','Jl. Raya Solo - Tawangmangu KM. 34, 3, RT. 01/03, Karang Wetan, Karang, Kec. Karangpandan, Kabupaten Karanganyar, Jawa Tengah 57791',2,-7.63182,111.106,'Agrowisata Amanah adalah destinasi wisata keluarga yang menggabungkan konsep edukasi, rekreasi, dan religi dalam satu kawasan. Terletak di jalur wisata Solo–Tawangmangu, tempat ini menawarkan suasana sejuk pegunungan serta berbagai wahana edukatif dan aktivitas luar ruang. Pengunjung bisa belajar tentang pertanian organik, beternak, hingga menjalani pelatihan karakter berbasis nilai-nilai Islam. Tempat ini sering digunakan sebagai lokasi outbound, kunjungan sekolah, dan wisata keluarga bernuansa islami, menjadikannya salah satu agrowisata terlengkap di Karanganyar.','\"{\\n  \\\"Outbound\\\": {\\n  \\\"TK\\\": 115500-242000,\\n  \\\"SD\\\": 115500-242000,\\n  \\\"SLB\\\": 115500-242000,\\n  \\\"Paintball\\\": 115500-242000,\\n  },\\n  \\\"Camping\\\": {\\n  \\\"Ceria Anak\\\": 258500-341000,\\n  \\\"Dewasa\\\": 258500-341000,\\n  },\\n  \\\"Paket Prasmanan\\\": 55000-77000\\n  }\\n }\"',115500.00,242000.00,4746,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(51,'5d1c2804-d35a-4e83-ba94-ab6252f890f9','telaga-kusuma-agrowisata-waterpark-5d1c28','Telaga Kusuma Agrowisata Waterpark','Matesih ke Selatan, Tawun, Tunggulrejo, Jumantono, Karanganyar Regency, Central Java 57782',2,-7.66626,111.046,'Telaga Kusuma Agrowisata Waterpark merupakan destinasi wisata yang menggabungkan konsep agrowisata dan rekreasi air. Terletak di lahan seluas 1,4 hektare, tempat ini menawarkan berbagai fasilitas seperti kolam renang dari mata air alami, taman bunga yang estetik, bioskop VR, serta area outbound dan camping.','{\"Bioskop VR\": {\"Weekday\": {\"Umum\": 10000}, \"Weekend\": {\"Umum\": 20000}}, \"Tiket Masuk\": {\"Weekday\": {\"Umum\": 10000}, \"Weekend\": {\"Umum\": 15000}}}',10000.00,20000.00,1266,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(52,'c2a3aee0-b8de-4e34-8fb7-5e983ff58239','agrowisata-kampoeng-karet-c2a3ae','Agrowisata Kampoeng Karet','Kenteng, Puntukrejo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.62269,111.104,'Agrowisata Kampoeng Karet merupakan destinasi wisata edukatif yang menawarkan suasana sejuk di tengah hutan karet. Tempat ini menyediakan berbagai fasilitas seperti kolam renang, area outbound, camping ground, serta spot-spot foto menarik, menjadikannya pilihan ideal untuk rekreasi keluarga dan kegiatan kelompok.','{\"Outbound\": {\"Anak\": 85000, \"Dewasa\": 90000, \"Family Gathering\": 130000}, \"Tiket Masuk\": {\"Weekday\": {\"Anak\": 7000, \"Dewasa\": 10000}, \"Weekend\": {\"Anak\": 6000, \"Dewasa\": 7000}}}',6000.00,130000.00,2091,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(53,'721f9b34-3143-4141-ba48-a433d7d79d63','agrowisata-jambu-merah-ngargoyoso-721f9b','Agrowisata Jambu Merah Ngargoyoso','Candi, RT.02/RW.04, Candi, Jatirejo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.58205,111.092,'Agrowisata Jambu Merah PUJA menawarkan pengalaman edukatif di tengah kebun jambu seluas sekitar \n 1 hektar. Pengunjung dapat memetik jambu langsung dari pohon, belajar budidaya jambu, serta menikmati berbagai olahan jambu seperti es krim dan keripik. Tempat ini juga menyediakan fasilitas outbound dan menerima kunjungan studi banding.','{\"Tiket Masuk\": {\"Umum\": 5000}}',5000.00,5000.00,93,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(54,'040f9279-369d-4fb8-9385-6580e02e7120','the-nice-park-solo-040f92','The Nice Park Solo','Jl. Mayor Achmadi, Kedunggong, Jeruksawit, Kec. Gondangrejo, Kabupaten Karanganyar, Jawa Tengah 57188',2,-7.50946,110.857,'The Nice Park Solo adalah destinasi wisata keluarga terbaru di Karanganyar yang menawarkan berbagai \n wahana bermain indoor dan outdoor. Dibuka pada Desember 2024, taman ini menyediakan beragam aktivitas seru dan edukatif untuk anak-anak serta fasilitas lengkap untuk kenyamanan pengunjung.','{\"Tiket Masuk\": {\"Umum\": 30000}}',30000.00,30000.00,530,3.9,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(55,'b4f1546a-ab8f-4d1d-9d07-172635744067','museum-karst-indonesia-b4f154','Museum Karst Indonesia','Jalan Raya Pracimantoro-Giritontro KM 4, Desa Gebangharjo, Kecamatan Pracimantoro, Kabupaten Wonogiri, Jawa Tengah',7,-8.04146,110.783,'Museum Karst Indonesia adalah museum geologi terbesar di Asia Tenggara yang didirikan pada tahun 2009 \n dan diresmikan oleh Presiden Susilo Bambang Yudhoyono. Museum ini menyajikan informasi lengkap tentang kawasan karst, termasuk proses pembentukannya, pemanfaatan oleh manusia purba, dan berbagai jenis batuan kapur yang ditemukan di Indonesia.','{\"Tiket Masuk\": {\"Umum\": 5000}}',5000.00,5000.00,1128,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(56,'4281d257-4cbd-43b4-b85f-aedc84e89897','goa-putri-kencono-4281d2','Goa Putri Kencono','Dusun Wonosobo, RT.3/RW.1, Gunungan, Desa Wonodadi, Kecamatan Pracimantoro, Kabupaten Wonogiri, Jawa Tengah 57664',7,-8.01948,110.793,'Goa Putri Kencono merupakan gua karst alami yang terletak di kawasan Gunung Sewu. Dengan panjang lorong sekitar 121 meter dan tinggi serta lebar sekitar 4 meter, gua ini menawarkan keindahan stalaktit dan stalagmit yang memukau. Terdapat tujuh ruangan di dalam gua yang masing-masing memiliki cerita dan fungsi tersendiri, seperti ruang tamu, ruang kebudayaan, dan ruang perpustakaan','{\"Tiket Masuk\": {\"Umum\": 5000}}',5000.00,5000.00,135,4.2,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(57,'3b7e7d6e-3948-418c-9a68-45c185a160ec','obyek-wisata-waduk-gajah-mungkur-wonogiri-3b7e7d','Obyek Wisata Waduk Gajah Mungkur Wonogiri','Godean, Sendang, Kecamatan Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57615',7,-7.84534,110.91,'Waduk Gajah Mungkur merupakan danau buatan yang dibangun di atas Sungai Bengawan Solo. Selain \n berfungsi sebagai irigasi dan pembangkit listrik, waduk ini juga menjadi destinasi wisata populer di Wonogiri. Pengunjung dapat menikmati berbagai aktivitas seperti wisata air, taman satwa, waterboom, dan spot foto menarik seperti jembatan kaca.','{\"Parkir\": {\"Bus\": 20000, \"Mobil\": 5000, \"Motor\": 2000, \"Mini Bus\": 10000}, \"Waterboom\": 15000, \"Tiket Masuk\": {\"Weekday\": 15000, \"Weekend\": 20000}, \"Wisata Perahu\": 10000}',15000.00,20000.00,9617,4.2,'','2025-06-18 18:26:39','2025-07-03 17:49:59'),(58,'0f0a6749-7e23-4cf3-baf1-0911b3062d0e','taman-satwa-gajah-mungkur-0f0a67','Taman Satwa Gajah Mungkur','Godean, Desa Sendang, Kecamatan\n  Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57615',7,-7.85529,110.914,'Taman Satwa Gajah Mungkur merupakan kebun binatang mini yang berfungsi sebagai lahan konservasi bagi berbagai satwa langka dan dilindungi. Terletak di kawasan Waduk Gajah Mungkur, taman ini menyajikan pengalaman edukatif dan rekreatif bagi pengunjung dari berbagai usia. Koleksi hewan yang menjadi daya tarik utama termasuk gajah, elang bondol, merak, siamang, jalak putih, rusa timor, orang utan, bulus, kasuari, dan lainnya.','{\"Parkir\": {\"Bus\": 20000, \"Mobil\": 5000, \"Motor\": 2000, \"Mini Bus\": 10000}, \"Tiket Masuk Kawasan Waduk Gajah Mungkur\": {\"Weekday\": 10000, \"Weekend\": 12000}}',10000.00,12000.00,303,3.9,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(59,'04d64afc-789a-4470-a6e6-9ef359b90322','gunung-sewu-geopark-04d64a','Gunung Sewu Geopark','Kawasan ini membentang di tiga kabupaten: Gunungkidul (Daerah Istimewa Yogyakarta), Wonogiri (Jawa Tengah), dan Pacitan (Jawa Timur).',7,-8.08333,110.583,'Gunung Lawu adalah gunung berapi yang terletak di perbatasan antara Jawa Tengah dan Jawa Timur, Indonesia, dengan ketinggian sekitar 3.265 meter di atas permukaan laut. Gunung ini dikenal sebagai salah satu tujuan pendakian populer di Jawa karena pemandangannya yang indah, jalur pendakian yang menantang, serta keanekaragaman flora dan fauna. Gunung Lawu juga memiliki nilai spiritual yang tinggi bagi masyarakat setempat, karena banyak yang menganggapnya sebagai tempat keramat. Pendakian ke puncak Gunung Lawu menawarkan pengalaman alam yang memukau, dengan udara segar dan pemandangan spektakuler, terutama saat matahari terbit.','5000',5000.00,5000.00,29,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(60,'76a9b597-3623-4af9-ac1c-00cbe9c24a44','bukit-cumbri-76a9b5','Bukit Cumbri','Desa Kepyar, Kecamatan \n Purwantoro, Kabupaten Wonogiri, Jawa Tengah, Indonesia',7,-7.84074,111.306,'Bukit Cumbri adalah destinasi wisata alam yang menawarkan pemandangan sabana hijau, lautan awan, \n serta panorama matahari terbit dan terbenam yang memukau. Dengan ketinggian sekitar 638 mdpl, bukit ini cocok untuk pendaki pemula dan menjadi tempat favorit untuk trekking, hiking, dan camping.','{\"Parkir\": {\"Mobil\": 10000, \"Sepeda Motor\": 5000}, \"Tiket Masuk\": {\"Umum\": 3500}, \"Paket Camping 2 Hari 1 Malam\": {\"Umum\": 250750}}',3500.00,250750.00,1692,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(61,'5ed50956-8586-42a7-ad3b-2bc1a6e08711','museum-manusia-purba-sangiran-klaster-dayu-5ed509','Museum Manusia Purba Sangiran Klaster Dayu','Desa Dayu, Kecamatan \n Gondangrejo, Kabupaten Karanganyar, Jawa Tengah, Indonesia',2,-7.47423,110.846,'Museum ini merupakan bagian dari Situs Sangiran yang diakui UNESCO sebagai Warisan Dunia. \n Klaster Dayu menyajikan informasi tentang lapisan tanah Sangiran dan berbagai artefak manusia purba, termasuk fosil Homo erectus.','{\"Tiket Masuk\": {\"Dewasa\": 5000, \"Anak-anak\": 2000}}',2000.00,5000.00,831,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(62,'940f75c6-a8d6-4ebe-8745-792db3b36070','taman-kridoanggo-sragen-940f75','Taman Kridoanggo Sragen','Jl. Sukowati No.488, Dusun Kebayanan Krajoyok, Sragen Wetan, Kecamatan Sragen, Kabupaten Sragen, Jawa Tengah 57211, Indonesia',3,-7.42595,111.028,'Taman Kridoanggo Sragen adalah Sebuah taman yang terletak di pusat kota Sragen yang menawarkan tempat bersantai dan tempat wisata kuliner. Terletak di Kabupaten Sragen provinsi Jawa Tengah, Taman Kridoanggo Sragen mudah diakses dengan berbagai moda transportasi.','{\"Tiket Masuk\": {\"Umum\": \"0\"}}',0.00,0.00,3624,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(63,'e4a4388f-0881-44f1-aaf1-bbe2a427d2b9','wisata-edukasi-poktan-mandiri-terpadu-e4a438','Wisata Edukasi Poktan Mandiri Terpadu','Desa Tanon, Kecamatan Tanon, Kabupaten Sragen, Jawa Tengah, Indonesia',3,-7.47423,110.914,'Wisata Edukasi POKTAN MANDIRI TERPADU merupakan destinasi agrowisata yang menawarkan \n pengalaman belajar langsung tentang pertanian dan peternakan. Pengunjung, terutama anak-anak, dapat terlibat dalam kegiatan seperti menanam padi, menangkap ikan, memerah susu kambing atau sapi, serta menikmati area bermain di lingkungan pertanian','{\"Tiket Masuk\": {\"Umum\": \"0\"}}',0.00,0.00,10,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(64,'4956e97a-b60d-4051-a69c-16436a33d3ab','ndayu-park-4956e9','Ndayu Park','Gembong RT 08/RW 04, Desa Saradan, Kecamatan Karangmalang, Kabupaten Sragen, Jawa Tengah 57222, Indonesia',3,-7.46355,110.992,'Ndayu Park Sragen merupakan destinasi wisata keluarga yang menawarkan berbagai wahana edukatif dan rekreatif. Terletak di lingkungan yang asri dengan udara sejuk, tempat ini menyediakan mini zoo, agrowisata, waterpark, outbound, serta berbagai fasilitas pendukung lainnya.','{\"mini_zoo\": 5000, \"outbound\": {\"hingga\": 100000, \"mulai_dari\": 75000}, \"tiket_masuk\": {\"dewasa\": 5000, \"anak_anak\": 3000}, \"kolam_renang\": {\"hari_biasa\": 8000, \"hari_libur\": 10000}, \"wahana_permainan\": {\"hingga\": 10000, \"mulai_dari\": 5000}}',3000.00,100000.00,2744,4.1,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(65,'bb26a2d2-58b0-4964-9b4d-e073a5d05e07','agrowisata-sejahtera-mandiri-miri-sragen-bb26a2','Agrowisata Sejahtera Mandiri Miri Sragen','Desa Doyong, Kecamatan Miri, Kabupaten Sragen, Jawa Tengah, Indonesia',3,-7.3444,110.815,'Di Kabupaten Sragen ada tempat wisata yang cocok untuk bersantai menghabiskan waktu berlibur dengan keluarga atau kerabat, nih. Berlokasi di Genengsari, Bagor, Kecamatan Miri, Agrowisata Sejahtera Mandiri hadir menawarkan destinasi yang cocok untuk rekreasi dan edukasi anak-anak.','{\"tiket_masuk\": {\"umum\": \"Rp 5.000\"}, \"kolam_renang_anak\": \"Rp 5.000\"}',5000.00,5000.00,56,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(66,'f71b9687-561b-402e-b9b6-277d660a76b1','taman-sukowati-sragen-f71b96','Taman Sukowati Sragen','Jalan Dr. Sutomo No. 5, Sine, Kecamatan Sragen, Kabupaten Sragen, Jawa Tengah 57213, Indonesia',3,-7.42231,111.007,'Taman Sukowati yang tepatnya berada di Jalan Dr Sutomo No. 5. Taman ini terbentang luas dengan keindahan yang dimilikinya. Selain itu taman ini juga memiliki danau yang cukup luas yang biasanya dijadikan masyarakat sekitar sebagai tempat memancing ikan. Udara yang sejuk dan asri memikat banyak orang berdatangan ke tempat wisata ini.','{\"tiket_masuk\": \"0\"}',0.00,0.00,975,4.3,'https://sragenkab.go.id/jelajah-sukowati-71.html','2025-06-18 18:26:39','2025-06-18 18:26:39'),(67,'1e4e3623-cd19-41f6-92a9-c222053e82ef','sadeyan-desa-wisata-edukasi-1e4e36','Sadeyan Desa Wisata Edukasi','MV3H+F53 Sadeyan Desa Wisata Edukasi, Kebayanan II, Jati, Kec. Sumberlawang, Kabupaten Sragen, Jawa Tengah 57272, Indonesia',3,-7.3444,110.878,'Sadeyan Desa Wisata Edukasi merupakan destinasi yang menawarkan pengalaman belajar sambil berwisata. Terletak di kawasan pedesaan yang asri, desa ini menyajikan berbagai aktivitas yang mengedukasi pengunjung tentang pertanian, budaya lokal, dan kehidupan masyarakat desa.','0',0.00,0.00,2,5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(68,'40f4f0d6-7b02-43e3-a6d2-bd6021c0d10d','elok-waterpark-40f4f0','Elok Waterpark','Elok Waterpark, RT.17/RW.05, Kebayanan Jetis, Pilangsari, Kec. Ngrampal, Kabupaten Sragen, Jawa Tengah 57252, Indonesia',3,-7.41222,111.047,'Elok Waterpark Sragen merupakan salah satu tempat wisata yang ada di Sragen dan menawarkan keseruan bagi pengunjungnya. Tempat ini merupakan tempat wisata air yang sangat cocok dikunjungi bersama anak maupun keluarga.','{\"parkir\": {\"mobil\": \"Rp 5.000\", \"motor\": \"Rp 3.000\"}, \"sewa_ban\": \"Rp 3.000\", \"tiket_masuk\": {\"weekday\": \"Rp 20.000\", \"weekend\": \"Rp 20.000\"}}',20000.00,20000.00,602,4.1,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(69,'3c8bcf34-6ec6-48d4-b27e-40be5f6f0611','waduk-kembangan-3c8bcf','Waduk Kembangan','Kembangan Lake, Kembangan, Mojorejo, Karangmalang, Sragen Regency, Central Java 57222, Indonesia',3,-7.3444,111.067,'Waduk Kembangan, atau dikenal juga sebagai Kembangan Lake, adalah danau buatan yang terletak di Desa Kembangan, Kecamatan Karangmalang, Kabupaten Sragen, Jawa Tengah. Terletak sekitar 10 km dari pusat kota Sragen , tempat ini menawarkan suasana tenang dan pemandangan alam yang memikat, menjadikannya destinasi favorit bagi wisatawan lokal maupun luar daerah.','0',0.00,0.00,714,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(70,'389f2de3-51c1-42d2-ab07-384ed6baf42b','wisata-sendang-kun-gerit-389f2d','Wisata Sendang Kun Gerit','Wisata Sendang Kun Gerit, Jalan Gemolong - Plupuh Dukuh Sidorejo RT.02, Kukungerit, Dusun 1, Jatibatur, Kec. Gemolong, Kabupaten Sragen, Jawa Tengah 57274, Indonesia',3,-7.3444,110.854,'Wisata Sendang Kun Gerit menyediakan berbagai fasilitas wisata yang dapat dinikmati oleh seluruh kalangan,dari anak-anak hingga orang dewasa.Wisata Sendang Kun Gerit menyuguhkan pemandangan yang alami,asri dan ramah lingkungan.','5000',5000.00,5000.00,1237,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(71,'cfda1c89-2aa7-444f-9d7b-63f56e27fd5c','gemolong-edupark-cfda1c','Gemolong Edupark','Gemolong Edupark (Taman Kota), Dusun 2, Gemolong, Sragen Regency, Central Java 57274, Indonesia',3,-7.3444,110.832,'Gemolong Edupark merupakan tempat wisata yang memadukan antara edukasi dan rekreasi menyenangkan di Kabupaten Sragen. Tempat wisata ini menjadi salah satu tempat yanag bisa dijadikan pilihan untuk menghabiskan waktu bersama keluarga.','0',0.00,0.00,3221,4.2,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(72,'db20242c-5384-4705-b8c6-598808a72d00','bumdes-sendang-pinilih-sendang-db2024','BUMDes Sendang Pinilih Sendang','BUMDes Sendang Pinilih Sendang, SEKRETARIAT BUMDES SENDANG PINILIH KELURAHAN SENDANG, Desa, Sendang, Kec. Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57651, Indonesia',7,-7.3444,110.912,'Keunikan dan keunggulan Desa Wisata Sendang Pinilih yakni adanya Paralayang. Jadi disini para pengunjung dapat merasakan terbang tandem paralayang. Hal ini menjadi unik karena satu-satunya yang ada di Kota Wonogiri.','0',0.00,0.00,977,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(73,'aecf2f8b-29ec-427d-b947-56318304c074','watu-cenik-wonogiri-aecf2f','Watu Cenik Wonogiri','5W27+25X Watu Cenik Wonogiri, Sendang, Kec. Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57615, Indonesia',7,-7.3444,110.913,'Berwisata ke daerah perbukitan memang menjadi favorit banyak orang lantaran keindahan pemandangan dari atas bukit. Inilah yang ditawarkan oleh Desa Sendang dengan sebagian wilayah perbukitannya. Salah satu destinasi wisata atas ketinggian di Wonogiri adalah Watu Cenik.','5000',5000.00,5000.00,395,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(74,'f4e2e028-95cb-4e53-866a-68c4a356547d','telaga-claket-f4e2e0','Telaga Claket','Telaga Claket, Jl. Claket Jl. Ngawen, Keblokan, Sendangijo, Kec. Selogiri, Kabupaten Wonogiri, Jawa Tengah 57652, Indonesia',7,-7.3444,110.908,'Terletak di kaki Bukit Widodaren, telaga ini menawarkan pemandangan alam yang memukau, dengan air yang jernih dan suasana sejuk yang ideal untuk bersantai.','{\"Tiket Masuk\": 10000}',10000.00,10000.00,1563,4.1,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(75,'ae774fcf-8368-49c8-b943-1bd9e9a472ee','puncak-joglo-ae774f','Puncak Joglo','5V3W+XH9 Puncak Joglo, Selopukang, Sendang Pinilih, Kec. Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57615, Indonesia',7,-7.3444,110.896,'Puncak Joglo adalah destinasi wisata di Desa Sendang, Kecamatan Wonogiri, yang terkenal dengan pemandangan Waduk Gajahmungkur yang indah, khususnya saat sunrise dan sunset. Puncak Joglo juga sering dijadikan lokasi untuk paragliding.','\"{\\n  \\\"Tiket Masuk\\\": 5000\\n  }\\n {\\n  \\\"Parkir\\\": 2000\\n  }\"',2500.00,2500.00,1027,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(76,'76075cec-bbe4-47ca-8191-a50398744c8a','girimanik-mountain-camp-76075c','Girimanik Mountain Camp','Girimanik mountain camp, RT.01/RW.06, Ngerapah, Setren, Slogohimo, Wonogiri Regency, Central Java, Indonesia',7,-7.3444,111.182,'Girimanik Mountain Camp adalah destinasi wisata alam yang menawarkan pengalaman berkemah di tengah suasana pegunungan yang sejuk dan asri. Terletak di kawasan Girimanik, tempat ini menyuguhkan panorama alam yang menakjubkan dengan latar hutan pinus, air terjun, dan pemandangan sunrise yang memukau.','{\"Tiket Masuk Anak\": 3000, \"Tiket Masuk Dewasa\": 5000}',3000.00,5000.00,320,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(77,'f4483a31-0140-4484-8f81-1a774f16fc93','wisata-soko-langit-f4483a','Wisata Soko Langit','66W2+QR7 Soko Langit, Nglarangan, Dusun Nglarangan, Conto, Kec. Bulukerto, Kabupaten Wonogiri, Jawa Tengah 57697, Indonesia',7,-7.3444,111.202,'Soko Langit adalah destinasi wisata alam yang menawarkan pengalaman unik berenang di kolam renang rooftop dengan panorama langsung ke Pegunungan Lawu. Terletak di ketinggian sekitar 1.000 meter di atas permukaan laut, tempat ini menyuguhkan pemandangan alam yang memukau dan udara pegunungan yang sejuk. Selain kolam renang, Soko Langit juga dilengkapi dengan berbagai fasilitas rekreasi dan edukasi, menjadikannya pilihan ideal untuk liburan keluarga maupun kegiatan komunitas.','\"{\\n \\\"Tiket Masuk \\\": 1-50000,\\n \\\"Tiket Masuk \\\": 50000-100000,\\n \\\"Tiket Masuk \\\": 100000-150000,\\n }\"',0.00,150000.00,1861,4.2,'','2025-06-18 18:26:39','2025-07-08 23:52:43'),(78,'7aeb1643-f54d-4b9d-aeb3-6807b21e551e','goa-resi-7aeb16','Goa Resi','GOA RESI, Jalan Goa Resi, Dusun Nglarangan, Conto, Bulukerto, Wonogiri Regency, Central Java 57697, Indonesia',7,-7.74319,111.205,'Goa Resi adalah destinasi wisata alam yang menawarkan keindahan formasi stalaktit dan stalagmit yang menakjubkan, terbentuk selama ribuan tahun. Terletak di kawasan perbukitan dengan udara sejuk, goa ini juga memiliki nilai sejarah karena ditemukan artefak-artefak purbakala yang menandakan pernah menjadi tempat tinggal manusia purba.','{\"Tiket Masuk \": 15000}',15000.00,15000.00,1144,4.6,'https://www.instagram.com/goaresi','2025-06-18 18:26:39','2025-06-18 18:26:39'),(79,'8f054f25-43e0-41d8-811d-a3a786663afa','gunung-gandul-wonogiri-8f054f','Gunung Gandul Wonogiri','5WM7+QXH Gunung Gandul Wonogiri, Area Hutan, Giriwono, Kec. Wonogiri, Kabupaten Wonogiri, Jawa Tengah 57613, Indonesia',7,-7.3444,110.915,'Gunung Gandul adalah destinasi wisata alam yang menawarkan panorama 360 derajat Kota Wonogiri dari ketinggian sekitar 600 meter di atas permukaan laut. Terletak hanya sekitar 10–15 menit dari pusat kota, tempat ini menjadi pilihan favorit untuk menikmati pemandangan kota, perbukitan, Waduk Gajah Mungkur, dan gugusan Pegunungan Seribu. Saat malam hari, pengunjung disuguhi keindahan city light yang memukau.','\"{\\n \\\"Tiket Masuk \\\": 5000\\n }\\n {\\n \\\"Camping ground \\\": 10000\\n }\"',5000.00,10000.00,74,4.1,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(80,'df320e5e-def2-4875-8c35-44ac10fd296f','candi-muncar-df320e','Candi Muncar','74MW+7R5 Candi Muncar, Siroto, Bubakan, Girimarto, Wonogiri Regency, Central Java 57683, Indonesia',7,-7.71656,111.147,'Meskipun bernama \"Candi\", Candi Muncar sebenarnya adalah sebuah telaga alami yang terletak di lereng Pegunungan Lawu Selatan pada ketinggian sekitar 1.170 meter di atas permukaan laut. Dikelilingi oleh pepohonan hijau dan udara sejuk, tempat ini menawarkan ketenangan dan keindahan alam yang memukau. Telaga ini juga menjadi sumber air bagi masyarakat sekitar dan menawarkan berbagai aktivitas rekreasi yang menarik.','\"{\\n \\\"Tiket Masuk \\\": 5000\\n }\\n {\\n \\\"Sewa sampan \\\": 10000:\\n  \\\"include pengemudi\\\": 15000\\n }\\n {\\n \\\"Pakan ikan\\\": 2000\\n }\"',2000.00,15000.00,1141,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(81,'ca61ae26-b106-4358-9d26-a7f3815af42c','girimanik-waterfall-ca61ae','Girimanik Waterfall','75F9+XRP Girimanik Waterfall, Ngerapah, Setren, Slogohimo, Wonogiri Regency, Central Java 57694, Indonesia',7,-7.3444,111.17,'Air Terjun Girimanik merupakan kawasan wisata alam yang terletak di lereng selatan Gunung Lawu. Kawasan ini terkenal dengan tiga air terjun utamanya:\n Air Terjun Manikmoyo: Memiliki ketinggian sekitar 70 meter dan aliran air yang deras, menjadikannya spot favorit untuk fotografi.\n Air Terjun Tejomoyo: Berada di tengah kawasan dengan ketinggian sekitar 30 meter. \n Air Terjun Condromoyo: Terletak paling jauh dari pintu masuk, menawarkan suasana yang lebih tenang dan alami.\n Selain keindahan alamnya, kawasan ini juga memiliki nilai spiritual dengan adanya petilasan Raden Mas Said dan sendang-sendang suci seperti Sendang Drajat dan Sendang Kanastren.','\"{\\n \\\"Tiket Masuk \\\": 5000\\n }\\n {\\n \\\"Parkir \\\" {\\n  \\\"Motor\\\": 2000\\n  \\\"Mobil\\\": 5000\\n  }\\n }\"',5000.00,5000.00,380,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(82,'2f4e08fd-17f7-44fe-bf2a-c171784037ba','istana-parnaraya-2f4e08','Istana Parnaraya','Parnaraya Palace, Istana Parnaraya, Kebonagung, Sidoharjo, Wonogiri Regency, Central Java 57682, Indonesia',7,-7.3444,111.057,'Terletak di Desa Kebonagung, Kecamatan Sidoharjo, Kabupaten Wonogiri, Istana Parnaraya adalah bangunan megah bergaya kolonial yang dibangun oleh pengusaha lokal, Suparno (biasa disebut Pak Parno). Fungsi utama bangunan ini adalah sebagai tempat pertemuan para sesepuh dan penyambutan tamu, termasuk wisatawan. Selain itu, terdapat gedung belakang yang memuat dokumentasi perjalanan sukses Pak Parno serta produk dan kesenian khas Wonogiri.','{\"Tiket Masuk \": 5000}',5000.00,5000.00,1363,4.3,'https://www.instagram.com/istana_parnaraya/?hl=id','2025-06-18 18:26:39','2025-06-18 18:26:39'),(83,'d2412744-6ad7-454d-bc5b-315668b40fcd','telogo-rowo-d24127','Telogo Rowo','Telogo Rowo, Rowo, Sumberejo, Batuwarno, Wonogiri Regency, Central Java 57674, Indonesia',7,-7.3444,110.99,'Telaga Rowo adalah wisata alam di Dusun Rowo, Desa Sumberejo, Batuwarno, Wonogiri, yang menyimpan legenda unik tentang Bima yang menciptakan rawa dalam semalam demi membantu masyarakat. Kini, telaga ini menjadi destinasi wisata keluarga yang menawarkan keindahan dan nuansa sejarah.','0',0.00,0.00,192,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(84,'5d156236-221d-45bb-ae86-1595b5c44234','kahyangan-dlepih-5d1562','Kahyangan Dlepih','Desa Dlepih, Kecamatan Tirtomoyo, Kabupaten Wonogiri, Jawa Tengah 57672, Indonesia',7,-7.97296,111.076,'Kahyangan Dlepih adalah destinasi wisata spiritual dan alam yang terletak di Desa Dlepih, Kecamatan \n Tirtomoyo, Kabupaten Wonogiri. Tempat ini dikenal sebagai petilasan Panembahan Senopati, pendiri Kerajaan Mataram Islam, dan dipercaya sebagai lokasi pertemuannya dengan Kanjeng Ratu Kidul. Dikelilingi oleh hutan pegunungan yang asri dan aliran Kali Kahyangan, kawasan ini menawarkan suasana yang tenang dan mistis, cocok untuk meditasi dan kegiatan spiritual lainnya.','{\"parkir\": {\"mobil\": \"3000\", \"sepeda_motor\": \"2000\"}, \"tiket_masuk\": {\"dewasa\": \"5000\", \"anak-anak\": \"2.500\"}}',2500.00,5000.00,248,4.7,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(85,'17ad7b2f-d6d7-4788-93ca-8b3a8ad78abd','pantai-nampu-17ad7b','Pantai Nampu','Pantai Nampu, Gunturharjo, Paranggupito, Wonogiri Regency, Central Java 57678, Indonesia',7,-7.3444,110.903,'Pantai Nampu terletak di selatan Wonogiri dan menawarkan keindahan pasir putih serta pemandangan laut lepas. Selain sebagai tempat wisata alam, Pantai Nampu juga bisa menjadi lokasi edukasi ekosistem pesisir. Pengunjung dapat mengenal lebih dekat tentang kehidupan biota laut, proses erosi, dan konservasi pantai.','{\"Tiket Masuk \": 2000}',2000.00,2000.00,3934,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(86,'0471f6e8-7d57-4d06-a907-864adf5c66aa','bukit-jonambang-0471f6','Bukit Jonambang','2W3X+3VX Bukit Jonambang, Dawe, Watuagung, Kec. Baturetno, Kabupaten Wonogiri, Jawa Tengah 57673, Indonesia',7,-7.3444,110.95,'Bukit Jonambang terletak di Wonogiri yang menawarkan pemandangan indah dari atas ketinggian. Tempat ini cocok untuk mengenalkan anak-anak dan keluarga tentang ekosistem pegunungan, flora, dan fauna lokal. Dari puncak bukit, pengunjung bisa menikmati panorama alam sembari belajar tentang pentingnya menjaga kelestarian hutan dan daerah hijau.','{\"tiket_masuk\": 5000}',5000.00,5000.00,265,4.1,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(87,'9cfa0fa6-371d-47a4-be05-518642d22a12','goa-tembus-pracimantoro-9cfa0f','Goa Tembus Pracimantoro','XQ6M+2FH Goa Tembus Pracimantoro, Unnamed Road, Mudal, Gebangharjo, Kec. Pracimantoro, Kabupaten Wonogiri, Jawa Tengah 57664, Indonesia',7,-7.3444,110.784,'Goa Tembus Pracimantoro terletak di kawasan Pracimantoro, Wonogiri, Goa ini disebut \"Tembus\" karena memiliki jalur tembus yang menghubungkan dua mulut gua. Di dalam goa, pengunjung bisa mempelajari formasi stalaktit dan stalagmit yang terbentuk selama ribuan tahun.','{\"tiket_masuk\": 5000}',5000.00,5000.00,117,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(88,'90633990-a590-4d7f-8843-c0eb65bdd260','taman-tirtonadi-906339','Taman Tirtonadi','Jl. A. Yani, Gilingan, Kec. Banjarsari, Kota Surakarta, Jawa Tengah 57134',1,-7.55128,110.82,'Taman Tirtonadi adalah tempat rekreasi sekaligus edukasi. Tempat ini dilengkapi dengan taman bermain, jalur jogging, dan fasilitas untuk belajar tentang lingkungan. Taman ini cocok untuk mengajarkan anak-anak tentang pentingnya menjaga kebersihan, daur ulang, dan penghijauan kota.','0',0.00,0.00,1348,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(89,'9ff7425d-3eb4-476e-b80b-1de367065a34','waduk-mulur-9ff742','Waduk Mulur','8V3H+9R4, Dondong, Mulur, Kec. Bendosari, Kabupaten Sukoharjo, Jawa Tengah 57528',5,-7.69508,110.879,'Waduk Mulur terletak di Sukoharjo yang berfungsi sebagai irigasi untuk pertanian sekaligus tempat wisata. Pengunjung dapat mempelajari bagaimana waduk berperan dalam pengelolaan sumber daya air, pengendalian banjir, dan irigasi. Di sekitar waduk, pengunjung juga dapat menikmati pemandangan sambil belajar tentang berbagai jenis tanaman dan ekosistem air tawar.','{\"tiket_masuk\": 5000}',5000.00,5000.00,1820,4.2,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(90,'d57c8c8f-1c95-46e1-885c-66abf57e043d','ekowisata-kali-talang-d57c8c','Ekowisata Kali Talang','Unnamed Road, Sambangrejo, Balerante, Kec. Kemalang, Kabupaten Klaten, Jawa Tengah 57484',4,-7.58278,110.462,'Ekowisata Kali Talang terletak di lereng Gunung Merapi tempat ini menawarkan pengalaman belajar tentang gunung berapi. Pengunjung dapat melihat lanskap vulkanik dari dekat, termasuk aliran lava yang membeku, material vulkanik, dan dampak letusan gunung berapi terhadap lingkungan sekitar. Tempat ini cocok untuk belajar geologi dan ekosistem pegunungan.','{\"tiket_masuk\": 5000}',5000.00,5000.00,2393,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(91,'6ea7f8a8-c4de-48ea-98fb-91d51af3301b','masjid-agung-al-aqsha-klaten-6ea7f8','Masjid Agung Al-Aqsha Klaten','8J68+2XW, Jl. Solo - Jogja, Peraksangkal, Jonggrangan, Kec. Klaten Utara, Kabupaten Klaten, Jawa Tengah 57435',4,-7.68963,110.616,'Masjid Agung Al Aqsha di Klaten merupakan destinasi religi yang juga memiliki nilai edukasi tinggi. Masjid ini terkenal dengan arsitektur megah bergaya Timur Tengah, dengan kubah besar dan menara yang menjulang. Pengunjung dapat belajar tentang sejarah masjid, seni ukir Islam, dan tradisi keagamaan masyarakat Klaten.','0',0.00,0.00,27733,4.8,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(92,'9c9c8877-853f-4cdf-97d3-b8f73d1aa755','taman-lampion-klaten-9c9c88','Taman Lampion Klaten','Gg. Tidar, Barenglor, Bareng Lor, Kec. Klaten Utara, Kabupaten Klaten, Jawa Tengah 57438',4,-7.69395,110.608,'Taman Lampion Klaten adalah salah satu destinasi wisata yang menarik di Kabupaten Klaten, Jawa Tengah. Tempat ini dikenal dengan keindahan lampion-lampion yang menghiasi taman, menjadikannya spot favorit bagi pengunjung, terutama saat malam hari ketika lampion-lampion tersebut menyala dan menciptakan suasana yang penuh warna dan magis.','5000',5000.00,10000.00,4526,4.2,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(93,'349e6f38-cfff-4312-9940-40e0536db004','hutan-kota-gergunung-349e6f','Hutan Kota Gergunung','8J93+WGV, Jl. Ki Ageng Gribig, Kwarsa, Gergunung, Kec. Klaten Utara, Kabupaten Klaten, Jawa Tengah 57434',4,-7.68008,110.604,'Destinasi ini sangat ramah untuk anak-anak dan juga sangat cocok untuk liburan keluarga. Pengelola hutan kota gergunung ini membuat beberapa spot foto untuk menarik para pengunjung, salah satu ikon dari destinasi ini adalah burung merpati yang cantik sehingga terdapat banyak rumah merpati atau biasa disebut pagupon.','2000',2000.00,2000.00,3430,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(94,'51809ff4-7258-4e2f-9126-a22e710466db','taman-wisata-jlengut-51809f','Taman Wisata Jlengut','8G8V+7C9, Jl jlengut indah Barepan, Geneng, Karangduren, Kec. Kebonarum, Kabupaten Klaten, Jawa Tengah 57486',4,-7.68401,110.544,'Taman Jlengut menyediakan wisata edukasi satwa, terdapat berbagai satwa yang ada di Taman Jlengut, seperti buaya, berbagai burung, berbagai jenis ular, kelinci, kambing, kura-kura, katak, kera, dan garangan.','5000',5000.00,6000.00,573,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(95,'72644ba4-d298-4cce-8528-8f523980e92d','obyek-wisata-kalimosodo-72644b','Obyek Wisata Kalimosodo','CH5W+JM8, Area Sawah, Sudimoro, Kec. Tulung, Kabupaten Klaten, Jawa Tengah',4,-7.59073,110.597,'Obyek wisata yang memanfaatkan pinggiran sungai Pusur dan bangunan saluran air peninggalan Belanda sebagai ikon utama itu menjadi salah satu tujuan destinasi wisata alternatif di Kabupaten Klaten.','5000',5000.00,5000.00,70,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(96,'cf716c3f-65af-47f1-ae9a-788b02c1be1b','gondang-winangoen-cf716c','Gondang Winangoen','Jl. Raya Solo - Yogyakarta KM.25, Karang Asem, Plawikan, Kec. Jogonalan, Kabupaten Klaten, Jawa Tengah 57452',4,-7.72184,110.561,'Museum Gondang Winangoen merupakan bagian dari Pabrik Gula (PG) Gondang Winangoen yang didirikan oleh NV Klatensche Cultuur Maatschappij yang berkedudukan di Amsterdam, Belanda pada tahun 1860.[3] Pabrik ini dikelola oleh NV Mirandolle Vaut dan Co yang berkedudukan di Semarang.','20000',2000.00,40000.00,1322,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(97,'74c3438e-fcd4-48ea-8c1e-5fcf05c7b786','taman-pancasila-74c343','Taman Pancasila','Jl. Lawu, Dompon, Karanganyar, Kec. Karanganyar, Kabupaten Karanganyar, Jawa Tengah 57711',2,-7.59748,110.951,'Taman Pancasila Karanganyar adalah ruang terbuka publik yang terletak di pusat kota Karanganyar. Taman ini dihiasi dengan patung-patung ikonik seperti Garuda, Ir. Soekarno, dan M. Hatta, serta tulisan besar \"Taman Pancasila\". Tempat ini menjadi destinasi favorit bagi keluarga untuk bersantai, bermain, dan menikmati suasana kota, terutama pada sore dan malam hari.','0',0.00,0.00,12360,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(98,'e3d8ab83-c91a-4576-badd-96ffafd8f1e0','wisata-bukit-sekipan-tawangmangu-e3d8ab','Wisata Bukit Sekipan Tawangmangu','Jl. Sekipan, Kramat, Kalisoro, Kec. Tawangmangu, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.66752,111.144,'Bukit Sekipan Tawangmangu adalah taman rekreasi keluarga yang memadukan keindahan alam pegunungan dengan beragam wahana modern dan edukatif. Menawarkan lebih dari 90 spot foto, area tematik, wahana permainan, hingga fasilitas penginapan, tempat ini cocok untuk liburan bersama keluarga maupun kegiatan kelompok.','{\"tiket_reguler\": {\"weekday\": 50000, \"weekend\": 60000}, \"tiket_terusan\": {\"weekday\": 80000, \"weekend\": 110000}, \"wahana_tambahan\": {\"monorail\": 20000, \"kora_kora\": 15000, \"kiddy_boat\": 10000, \"bom_bom_car\": 25000, \"kereta_mini\": 10000, \"super_rally\": 20000, \"komidi_putar\": 10000, \"mini_coaster\": 25000}, \"tiket_bukit_sekipan_night\": {\"harga\": 50000}}',50000.00,110000.00,12683,4.4,'http://www.bukitsekipan.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(99,'300c6a77-8f1d-4171-aee6-8d391081a11f','the-lawu-park-300c6a','The Lawu Park','Bulakrejo, Gondosuli Kidul, Gondosuli, Kec. Tawangmangu, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.66341,111.176,'The Lawu Park adalah taman rekreasi keluarga yang terletak di kaki Gunung Lawu, menawarkan berbagai wahana permainan, spot foto, dan penginapan dengan latar belakang panorama alam yang indah. Dengan luas sekitar 4,5 hektare, tempat ini cocok untuk liburan keluarga, gathering, maupun kegiatan edukatif.','{\"Weekday\": 20000, \"Weekend\": 25000, \"Hari libur\": 25000}',20000.00,25000.00,17472,4.5,'https://instagram.com/the_lawupark','2025-06-18 18:26:39','2025-06-18 18:26:39'),(100,'316e6520-14ab-4fa4-a7c1-dbbeaace6c3f','candi-kethek-316e65','Candi Kethek','C546+F3W lereng lawu, Anggrasmanis, Gumeng, Kec. Jenawi, Kabupaten Karanganyar, Jawa Tengah 57794',2,-7.59359,111.16,'Candi Kethek adalah situs candi Hindu bercorak megalitik yang diperkirakan berasal dari abad ke-15 hingga ke-16 Masehi. Terletak di lereng barat Gunung Lawu, candi ini memiliki struktur punden berundak dengan empat teras. Pada teras pertama terdapat arca kura-kura yang dipercaya sebagai jelmaan Dewa Wisnu. Candi ini menawarkan suasana tenang dan asri, cocok untuk wisata sejarah dan spiritual.','{\"tiket_masuk\": {\"weekday\": 7500, \"weekend\": 10000}}',7500.00,10000.00,208,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(101,'5ce83bc9-9fd4-44ee-8351-a2db9371130a','taman-wisata-sapta-tirta-5ce83b','Taman Wisata Sapta Tirta','9394+5X8, Jl. TP Joko Songo, Bt. Argotiloso, Pablengan, Kec. Matesih, Kabupaten Karanganyar, Jawa Tengah 57781',2,-7.63183,111.057,'Taman Wisata Sapta Tirta Pablengan adalah destinasi wisata bersejarah yang terletak di kaki Gunung Lawu. Tempat ini terkenal dengan tujuh sumber mata air alami yang masing-masing memiliki rasa dan khasiat berbeda, seperti air soda, air hangat, air hidup, dan air urus-urus. Selain sebagai tempat rekreasi, kawasan ini juga memiliki nilai spiritual dan sejarah, menjadikannya tujuan wisata yang unik dan menarik.','{\"tiket_masuk\": {\"dewasa\": 7000, \"anak_anak\": 7000}}',7000.00,7000.00,731,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(102,'c199a2a6-5305-45cd-a5c0-40faaaafb578','situs-matesih-c199a2','Situs Matesih','83W5+3CH, Jl. Raya Matesih-Tawangmangu, Area Sawah, Karangbangun, Kec. Matesih, Kabupaten Karanganyar, Jawa Tengah 57781',2,-7.6545,111.059,'Situs Watu Kandang adalah peninggalan zaman Megalitikum yang terletak di lereng barat Gunung Lawu. Situs ini terdiri dari ratusan batu menhir yang tersusun membentuk pola tertentu, menyerupai kandang. Lokasinya berada di tengah area persawahan, memberikan suasana alami dan tenang bagi pengunjung.','{\"tiket_masuk\": {\"umum\": 5000}}',5000.00,5000.00,322,4.4,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(103,'477fc5ad-a5e0-47dc-9f26-e0cd5bf9d334','pura-pasekan-agung-477fc5','Pura Pasekan Agung','93JM+X7X, Pasekan, RT.6/RW.5, Gedangan, keprabon, Kec. Karangpandan, Kabupaten Karanganyar, Jawa Tengah 57791',2,-7.61726,111.083,'Pura Pasekan Agung merupakan tempat ibadah umat Hindu yang memiliki arsitektur khas Bali dan terletak di lereng Gunung Lawu. Pura ini dikenal sebagai induk dari pura-pura Pasek lainnya yang ada di Bali. Meskipun fungsi utamanya adalah sebagai tempat peribadatan, pura ini juga menarik minat wisatawan karena keindahan arsitekturnya dan suasana spiritual yang kental.','0',0.00,0.00,397,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(104,'f8d69ac1-f5ae-4b2e-a214-0f18394acbac','gua-maria-sendang-pawitra-f8d69a','Gua Maria Sendang Pawitra','848F+26P, Tawangmangu, Karanganyar, Sendang, Sepanjang, Surakarta, Kabupaten Karanganyar, Jawa Tengah 57792',2,-7.68466,111.123,'Gua Maria Sendang Pawitra adalah tempat ziarah Katolik yang terletak di lereng Gunung Lawu. Nama \"Pawitra\" berasal dari bahasa Sanskerta yang berarti \"tempat penyucian diri\". Di lokasi ini terdapat sendang (sumber mata air) yang digunakan untuk berkat air suci. Suasana alam pegunungan yang sejuk dan tenang menjadikan tempat ini ideal untuk berdoa dan refleksi spiritual.','0',0.00,0.00,93,4.6,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(105,'e413cff6-288e-4356-804f-ce277afa8db4','taman-satwa-kemuning-e413cf','Taman Satwa Kemuning','RT.001/RW.002, Spranten, Kemuning, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.6036,111.125,'Taman Satwa Kemuning adalah kebun binatang mini yang dikelola secara swadaya oleh masyarakat setempat. Berlokasi di kawasan perbukitan yang sejuk, taman ini menampung lebih dari 30 jenis satwa, termasuk hewan eksotis seperti iguana albino, python reticulatus albino, dan rusa tutul. Pengunjung dapat berinteraksi langsung dengan satwa, memberi makan, serta menikmati berbagai aktivitas edukatif dan rekreasi.','{\"weekday\": 10000, \"weekend\": 15000}',10000.00,15000.00,172,4.7,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(106,'0722122d-9856-486c-965b-1a6ca71f4a47','pesanggrahan-pracimoharjo-072212','Pesanggrahan Pracimoharjo','Krapyak, Paras, Kec. Cepogo, Kabupaten Boyolali, Jawa Tengah 57362',6,-7.52325,110.54,'Pesanggrahan Pracimoharjo adalah bangunan bersejarah peninggalan Keraton Surakarta yang dibangun sekitar tahun 1803–1804 oleh Paku Buwono IV dan diperluas oleh Paku Buwono X. Terletak di lereng timur Gunung Merapi, tempat ini dahulu digunakan sebagai tempat peristirahatan raja dan kini menjadi lokasi ziarah spiritual yang populer, terutama di kalangan pelajar dan mahasiswa yang memohon kelancaran studi dan kehidupan pribadi.','0',0.00,0.00,240,4.3,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(107,'15f67b78-d71c-4c0e-8c0f-3ed6c3e938c3','wisata-edukasi-religi-qolbu-boyolali-15f67b','Wisata Edukasi Religi Qolbu Boyolali','Tambak, Dusun Sukuh, Berjo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.52032,110.608,'Wisata Edukasi Religi Qolbu Boyolali adalah destinasi wisata religi yang terletak di Desa Karanggeneng, Kecamatan Boyolali Kota, Kabupaten Boyolali, Jawa Tengah. Dibangun di atas lahan seluas sekitar 3 hektare yang sebelumnya merupakan bekas pasar hewan, tempat ini menyajikan replika berbagai lokasi penting dalam ibadah haji dan umrah, seperti Ka\'bah, Bukit Shafa dan Marwah, Masjid Nabawi, Jabal Rahmah, serta tempat minum air zamzam. Dengan desain yang menyerupai suasana di Tanah Suci, WER Qolbu memberikan pengalaman edukatif bagi pengunjung untuk memahami dan mempraktikkan tata cara ibadah haji dan umrah secara langsung. Tempat ini juga dirancang untuk memfasilitasi kegiatan manasik haji dan umrah, meditasi, zikir, serta diskusi spiritual, menjadikannya sebagai sarana pembelajaran dan refleksi spiritual yang mendalam.','\"{\\n  \\\"Pelajar\\\": 10000,\\n  \\\"Umum\\\": 20000,\\n }\"',10000.00,20000.00,536,4.5,'https://qolbu.destinasiboyolali.com/','2025-06-18 18:26:39','2025-06-18 18:26:39'),(108,'423b8400-6004-4d38-93f1-40692d174d99','museum-r-hamong-wardoyo-423b84','Museum R. Hamong Wardoyo','7VCR+57J Dusun I, RT.03/RW.01, Plesan, Kec. Nguter, Kabupaten Sukoharjo, Jawa Tengah 57571',5,-7.53155,110.619,'Museum R. Hamong Wardoyo di Boyolali merupakan destinasi wisata edukasi yang menampilkan kekayaan sejarah dan budaya lokal. Bangunannya yang unik menyerupai piramida dengan atap kaca transparan mengingatkan pada Museum Louvre di Paris. Di dalamnya, pengunjung dapat menjelajahi berbagai koleksi, termasuk arca dari masa Hindu-Buddha, diorama sejarah Boyolali, replika patung ikonik, serta kereta kencana. Tangga spiral yang menghubungkan dua lantai museum menambah pengalaman visual yang menarik bagi pengunjung.','0',0.00,0.00,741,4.5,'','2025-06-18 18:26:39','2025-06-18 18:26:39'),(109,'803489c9-18bb-40d4-b284-0d01cb498c59','kidoland-803489','Kidoland','Tambak, Dusun Sukuh, Berjo, Kec. Ngargoyoso, Kabupaten Karanganyar, Jawa Tengah 57793',2,-7.72931,110.891,'Kidoland adalah taman wisata edukasi yang menawarkan berbagai wahana interaktif untuk anak-anak dan keluarga. Terletak di kawasan pegunungan yang sejuk, tempat ini menyediakan pengalaman belajar yang menyenangkan melalui kegiatan seperti berinteraksi dengan hewan di mini zoo, bermain di kolam renang, serta mengikuti kegiatan outbound dan pertanian organik.','{\"Weekday\": 10000, \"Weekend\": 12000}',10000.00,12000.00,793,4.3,'https://wisatakidoland.com/','2025-06-18 18:26:39','2025-06-18 18:26:39');
